datosF = {
  regenerar;
  const medias = [10, 10 + separacion, 10 + 2 * separacion];
  const nombres = ["A", "B", "C"];
  const out = [];
  medias.forEach((m, i) =&gt; {
    const gen = d3.randomNormal(m, ruido);
    for (let j = 0; j &lt; nGrupoF; j++) out.push({ grupo: nombres[i], valor: gen() });
  });
