anovaF = {
  const grupos = d3.group(datosF, d =&gt; d.grupo);
  const todos = datosF.map(d =&gt; d.valor);
  const granMedia = d3.mean(todos);
  let ssb = 0, ssw = 0;
  for (const [, vals] of grupos) {
    const v = vals.map(d =&gt; d.valor), m = d3.mean(v);
    ssb += v.length * Math.pow(m - granMedia, 2);
    ssw += d3.sum(v, x =&gt; Math.pow(x - m, 2));
  }
  const k = grupos.size, N = todos.length;
  const d1 = k - 1, d2 = N - k;
  const F = (ssb / d1) / (ssw / d2);
  return { ssb, ssw, d1, d2, F, p: betaiF(d2 / 2, d1 / 2, d2 / (d2 + d1 * F)) };
}







gammlnF = (x) =&gt; {
  const cof = [76.18009172947146, -86.50532032941677, 24.01409824083091,
               -1.231739572450155, 0.1208650973866179e-2, -0.5395239384953e-5];
  let y = x, tmp = x + 5.5;
  tmp -= (x + 0.5) * Math.log(tmp);
  let ser = 1.000000000190015;
  for (let j = 0; j &lt; 6; j++) ser += cof[j] / ++y;
  return -tmp + Math.log(2.5066282746310005 * ser / x);
}







betacfF = (a, b, x) =&gt; {
  const qab = a + b, qap = a + 1, qam = a - 1;
  let c = 1, d = 1 - qab * x / qap;
  if (Math.abs(d) &lt; 1e-300) d = 1e-300;
  d = 1 / d;
  let h = d;
  for (let m = 1; m &lt;= 300; m++) {
    const m2 = 2 * m;
    let aa = m * (b - m) * x / ((qam + m2) * (a + m2));
    d = 1 + aa * d; if (Math.abs(d) &lt; 1e-300) d = 1e-300;
    c = 1 + aa / c; if (Math.abs(c) &lt; 1e-300) c = 1e-300;
    d = 1 / d; h *= d * c;
    aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2));
    d = 1 + aa * d; if (Math.abs(d) &lt; 1e-300) d = 1e-300;
    c = 1 + aa / c; if (Math.abs(c) &lt; 1e-300) c = 1e-300;
    d = 1 / d;
    const del = d * c; h *= del;
    if (Math.abs(del - 1) &lt; 1e-12) break;
  }
  return h;
}







betaiF = (a, b, x) =&gt; {
  if (x &lt;= 0) return 0;
  if (x &gt;= 1) return 1;
  const bt = Math.exp(gammlnF(a + b) - gammlnF(a) - gammlnF(b)
             + a * Math.log(x) + b * Math.log(1 - x));
  return x &lt; (a + 1) / (a + b + 2)
    ? bt * betacfF(a, b, x) / a
    : 1 - bt * betacfF(b, a, 1 - x) / b;
}







